      this.emit("participantsSelected", { data: [this.subject] });
      this.announce(
        `Subject ${this.subject}. ` + ["AE", "LB", "EX", "CM"].map((code) => plural3(counts[code] || 0, DOMAIN_NOUNS[code])).join(", ") + "."
      );
